-- Load facilities.DimDataSource (dimension, SCD type 1).
-- One stored procedure per destination table (DE Policy v2, 5.3).
-- Generated by `python -m fde render` from models/gold/facilities/DimDataSource.yml. Do not edit: change the spec and render again.

CREATE OR ALTER PROCEDURE [facilities].[LoadDimDataSource]
    @LoadDate date,
    @LoadStepID varchar(36)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Now datetime2(6) = SYSUTCDATETIME();
    DECLARE @MaxKey bigint = (SELECT COALESCE(MAX([DimDataSource_SK]), 0)
                              FROM [facilities].[DimDataSource] WHERE [DimDataSource_SK] > 0);

    MERGE [facilities].[DimDataSource] AS target
    USING (
        SELECT
            CAST(s.[DataSource_BK] AS varchar(20)) AS [DataSource_BK],
            CAST(s.[SourceName] AS varchar(500)) AS [SourceName],
            CAST(s.[SourceUrl] AS varchar(1000)) AS [SourceUrl],
            @MaxKey + ROW_NUMBER() OVER (ORDER BY s.[DataSource_BK]) AS [NewKey]
        FROM [stage].[DimDataSourceSource] AS s
    ) AS source
    ON target.[DataSource_BK] = source.[DataSource_BK]
    WHEN MATCHED AND (
        (target.[SourceName] <> source.[SourceName] OR (target.[SourceName] IS NULL AND source.[SourceName] IS NOT NULL) OR (target.[SourceName] IS NOT NULL AND source.[SourceName] IS NULL))
        OR (target.[SourceUrl] <> source.[SourceUrl] OR (target.[SourceUrl] IS NULL AND source.[SourceUrl] IS NOT NULL) OR (target.[SourceUrl] IS NOT NULL AND source.[SourceUrl] IS NULL))
    ) THEN UPDATE SET
        [SourceName] = source.[SourceName],
        [SourceUrl] = source.[SourceUrl],
        [LastUpdateLoadStepID] = @LoadStepID,
        [LastUpdateTimestamp] = @Now
    WHEN NOT MATCHED BY TARGET THEN INSERT (
        [DimDataSource_SK],
        [DataSource_BK],
        [SourceName],
        [SourceUrl],
        [InsertLoadStepID],
        [InsertTimestamp],
        [LastUpdateLoadStepID],
        [LastUpdateTimestamp]
    ) VALUES (
        source.[NewKey],
        source.[DataSource_BK],
        source.[SourceName],
        source.[SourceUrl],
        @LoadStepID,
        @Now,
        @LoadStepID,
        @Now
    );
END
GO
